const $=id=>document.getElementById(id);let toastTimer;function toast(message){$('toast').textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').textContent='',4500)}document.querySelectorAll('[data-note]').forEach(b=>b.addEventListener('click',()=>toast(b.dataset.note)));$('collapse').onclick=()=>{const collapsed=$('app').classList.toggle('collapsed');$('collapse').setAttribute('aria-expanded',String(!collapsed));$('collapse').setAttribute('aria-label',collapsed?'展开侧栏':'折叠侧栏')};

let candidateScene='ready';
const availableEngines=['llama-server b6800 · 最新下载','inference-engine · 用户引擎'];
function candidateState(scene){
 candidateScene=scene;
 document.querySelectorAll('[data-candidate-scene]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.candidateScene===scene)));
 const names=scene==='empty'?[]:scene==='revoked'?[availableEngines[1]]:availableEngines;
 $('engine').replaceChildren(...names.map(name=>new Option(name,name)));
 $('engine').disabled=scene==='empty';$('engine').selectedIndex=scene==='ready'?0:-1;
 $('candidate').disabled=scene!=='ready';
 const warning=$('candidate-warning');warning.hidden=scene==='ready';warning.replaceChildren();
 if(scene==='empty')warning.append('没有可用的引擎，请到模型页下载推荐引擎');
 if(scene==='revoked'){
  const badge=document.createElement('span');badge.className='badge invalid-choice';badge.textContent='当前选择不可用';warning.append(badge);
  const reason=document.createElement('p');reason.textContent='llama-server b6800 · 引擎运行库不完整。请重新选择可用引擎。';warning.append(reason);
 }
 if(scene!=='ready'){const link=document.createElement('a');link.href='models-page.html';link.textContent='到模型页'+(scene==='empty'?'下载推荐引擎':'重选');warning.append(' ',link)}
}
document.querySelectorAll('[data-candidate-scene]').forEach(b=>b.onclick=()=>candidateState(b.dataset.candidateScene));
$('checking-demo').onchange=()=>{$('engine-checking').hidden=!$('checking-demo').checked};
$('engine').onchange=()=>{if($('engine').value){$('candidate').disabled=false;$('candidate-warning').hidden=true}};
$('model').onchange=()=>{$('model-summary').textContent='测评模型：'+$('model').value+($('model').selectedIndex===0?'（架构 llama · 约 2.1 GiB）':'（架构 Qwen3 · 约 4.9 GiB）')};
candidateState('ready');
let generation=0,busy=false;const phases=['准备','设备检查','候选','启动与绑定','运行','报告核验'];
function stage(scene){generation++;busy=false;$('scene').value=scene;const index=['prepare','device','candidate','bind','run','report'].indexOf(scene);$('environment').hidden=scene!=='prepare';['device','candidate','bind','run','report'].forEach(s=>$(s+'-panel').hidden=s!==scene);document.querySelectorAll('.steps li').forEach((e,i)=>{e.removeAttribute('aria-current');if(i===index)e.setAttribute('aria-current','step')});$('phase').textContent='当前：'+phases[index];$('stage-progress').value=index;$('stage-description').textContent='已完成 '+index+' / 6 个阶段，不表示样本完成率。';$('bind-error').hidden=true;document.querySelectorAll('#bind-panel button,#bind-panel input,#bind-panel select').forEach(b=>b.disabled=false);$('service-status').textContent='已停止 · 等待启动';flow(0);$('core').textContent='zh-core · '+(index<3?'待创建候选':index===3?'待绑定':'已绑定');$('pelican').textContent='zh-svg-pelican · '+(index<3?'待创建候选':index===3?'待绑定':'已绑定');$('cancel').hidden=true;$('run').disabled=false;$('scene').disabled=false;$('queue').textContent='尚无排队任务。完成绑定后可启动默认双题包测评。';$('queue-badge').textContent='无活动任务'}
function flow(n){document.querySelectorAll('[data-flow]').forEach(e=>{e.removeAttribute('aria-current');if(Number(e.dataset.flow)===n)e.setAttribute('aria-current','step')})}
function status(text,n,active){$('service-status').replaceChildren();if(active){const s=document.createElement('span');s.className='spinner';s.setAttribute('aria-hidden','true');$('service-status').append(s,' ')}$('service-status').append(text);flow(n)}
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function bind(external=false,mismatch=false,pid=''){if(busy)return;busy=true;const token=++generation;const fail=mismatch||$('fail').checked;$('bind-error').hidden=true;document.querySelectorAll('#bind-panel button,#bind-panel input,#bind-panel select').forEach(b=>b.disabled=true);if(!external){status('starting · 正在启动引擎',1,true);await wait(900);if(token!==generation)return;status('running · 健康检查通过，尚未绑定',2,false);await wait(900)}else{status('running · 正在核验 PID '+pid+' 的服务身份',2,true);await wait(900)}if(token!==generation)return;status('绑定中 · zh-core',3,true);await wait(900);if(token!==generation)return;if(mismatch){failure('zh-core');return}$('core').textContent='zh-core · 已绑定';status('绑定中 · zh-svg-pelican',3,true);await wait(900);if(token!==generation)return;if(fail){failure('zh-svg-pelican');return}$('pelican').textContent='zh-svg-pelican · 已绑定';status('已绑定 · 两个题包均已完成绑定',4,false);toast('双题包绑定完成，可启动测评。');await wait(1200);if(token!==generation)return;stage('run');toast('两个题包已绑定，已进入运行阶段。')}
function failure(bundle){busy=false;status('running · 服务仍在运行，绑定已停止',2,false);$(bundle==='zh-core'?'core':'pelican').textContent=bundle+' · 绑定失败';$('bind-error').hidden=false;$('bind-error').textContent=bundle+' 绑定失败：启动参数与候选不一致（startup_arguments_mismatch）。请核对引擎与候选配置后重新发起绑定；不会自动重试。';document.querySelectorAll('#bind-panel button,#bind-panel input,#bind-panel select').forEach(b=>b.disabled=false);$('start').disabled=true;}
$('scene').onchange=e=>stage(e.target.value);$('prepare').onclick=()=>{stage('device');toast('示例工作区已初始化。')};$('device').onclick=()=>{stage('candidate');toast('示例设备检查已完成。')};$('candidate').onclick=()=>{$('chosen-engine').textContent=$('engine').value;$('chosen-model').textContent=$('model').value;stage('bind')};$('start').onclick=()=>bind();document.querySelectorAll('.external').forEach(b=>b.onclick=()=>bind(true,b.dataset.pid==='7310',b.dataset.pid));$('manual').onclick=()=>{let valid;try{const u=new URL($('endpoint').value);valid=['127.0.0.1','localhost','[::1]'].includes(u.hostname)&&u.protocol==='http:'}catch{valid=false}$('endpoint').setAttribute('aria-invalid',String(!valid));$('endpoint-error').hidden=valid;if(!valid){$('endpoint-error').textContent='请输入有效的本机 HTTP endpoint，例如 http://127.0.0.1:8080。';$('endpoint').focus();return}bind(true,$('process').value==='7310',$('process').value)};
$('run').onclick=()=>{$('run').disabled=true;$('scene').disabled=true;$('cancel').hidden=false;$('queue-badge').textContent='运行中 · 示例';$('queue').innerHTML='<span class="spinner" aria-hidden="true"></span> zh-core · 运行中；zh-svg-pelican · 等待前项结束。<p class="muted">样本进度缺测：尚未收到冻结题集合计数。服务内存缺测：等待首个采样。</p>'};$('cancel').onclick=async()=>{$('cancel').disabled=true;$('queue').textContent='取消中／等待收尾 · 保留已产生的证据。';await wait(900);$('queue').textContent='已取消 · 当前运行已收尾；后续题包未启动。';$('queue-badge').textContent='已取消';$('cancel').hidden=true;$('cancel').disabled=false;$('scene').disabled=false;$('run').disabled=false};$('report').onclick=()=>{$('report-status').textContent='示例：新报告 report-20261015-02 已生成，离线核验通过。';toast('新报告已生成并核验。')};stage('candidate');
